39	          <span className="text-lg font-bold text-white">K</span>
40	        </div>
41	        <h1 className="text-xl font-bold text-zinc-900">Masuk ke KasirKu</h1>
42	        <p className="mt-1 text-sm text-zinc-500">
43	          Masuk dengan akun pemilik toko kamu
44	        </p>
45	      </div>
46	
47	      <form onSubmit={handleSubmit} className="space-y-4">
48	        <div>
49	          <label htmlFor="email" className="mb-1 block text-xs font-medium text-zinc-600">
50	            Email
51	          </label>
52	          <input
53	            id="email"
54	            type="email"
55	            autoComplete="email"
56	            required
57	            value={email}
58	            onChange={(e) => setEmail(e.target.value)}
59	            className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm transition-shadow focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
60	            placeholder="kamu@toko.com"
61	          />
62	        </div>
63	        <div>
64	          <div className="mb-1 flex items-center justify-between">
65	            <label htmlFor="password" className="block text-xs font-medium text-zinc-600">
66	              Password
67	            </label>
68	            <Link href="/forgot-password" className="text-xs font-medium text-brand-600 hover:underline">
69	              Lupa password?
70	            </Link>
71	          </div>
72	          <input
73	            id="password"
74	            type="password"
75	            autoComplete="current-password"
76	            required
77	            value={password}
78	            onChange={(e) => setPassword(e.target.value)}
79	            className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm transition-shadow focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
80	            placeholder="••••••••"
