1	import { notFound, redirect } from "next/navigation";
2	import { createClient } from "@/lib/supabase/server";
3	import { getSubscriptionAccess } from "@/lib/billing/status";
4	import { isFinancePlan } from "@/lib/billing/plans";
5	import DashboardShell from "./dashboard-shell";
6	
7	export default async function BusinessDashboardLayout({
8	  children,
9	  params,
10	}: {
11	  children: React.ReactNode;
12	  params: Promise<{ businessId: string }>;
13	}) {
14	  const { businessId } = await params;
15	  const supabase = await createClient();
16	
17	  const [{ data: business }, { data: userData }, access] = await Promise.all([
18	    supabase
19	      .from("businesses")
20	      .select("id, name, business_type, owner_id")
21	      .eq("id", businessId)
22	      .single(),
23	    supabase.auth.getUser(),
24	    getSubscriptionAccess(supabase, businessId),
25	  ]);
26	
27	  if (!business) {
28	    notFound();
29	  }
30	
31	  const isOwner = business.owner_id === userData.user?.id;
32	  let permissions: string[] = [];
33	
34	  if (!isOwner) {
35	    const { data: staff } = await supabase
36	      .from("business_staff")
37	      .select("permissions, active")
38	      .eq("business_id", businessId)
39	      .eq("user_id", userData.user!.id)
40	      .maybeSingle();
41	
42	    if (!staff || !staff.active) {
43	      notFound();
44	    }
45	    permissions = staff.permissions;
46	  }
47	
48	  if (access.locked) {
49	    redirect(`/business/${businessId}/billing`);
50	  }
51	
52	  return (
53	    <DashboardShell
54	      businessId={businessId}
55	      businessName={business.name}
56	      businessType={business.business_type as "fnb" | "retail" | "tiket"}
57	      userEmail={userData.user?.email ?? ""}
58	      billingPastDuePeriodEnd={access.status === "past_due" ? access.periodEnd : null}
59	      trialPeriodEnd={access.status === "trialing" ? access.periodEnd : null}
60	      isFinanceOnly={isFinancePlan(access.planCode)}
61	      isOwner={isOwner}
62	      permissions={permissions}
63	    >
64	      {children}
65	    </DashboardShell>
66	  );
67	}
