110	export async function createBusiness(
111	  _prevState: CreateBusinessState,
112	  formData: FormData,
113	): Promise<CreateBusinessState> {
114	  const supabase = await createClient();
115	  const {
116	    data: { user },
117	  } = await supabase.auth.getUser();
118	
119	  if (!user) {
120	    redirect("/login");
121	  }
122	
123	  const name = (formData.get("name") as string)?.trim();
124	  const businessType = formData.get("business_type") as string;
125	
126	  if (!name) {
127	    return { error: "Nama toko wajib diisi." };
128	  }
129	  if (businessType !== "fnb" && businessType !== "retail" && businessType !== "tiket") {
130	    return { error: "Pilih jenis bisnis dulu." };
131	  }
132	
133	  const { data: business, error } = await supabase
134	    .from("businesses")
135	    .insert({
136	      owner_id: user.id,
137	      name,
138	      business_type: businessType,
139	    })
140	    .select("id")
141	    .single();
142	
143	  if (error || !business) {
144	    return { error: error?.message ?? "Gagal membuat bisnis." };
145	  }
146	
147	  // Grants a 3-day trial (hardcoded server-side in the RPC) so a new owner
148	  // can look around before being asked to pick and pay for a plan — see
149	  // start_trial() in 20260725110000_trial_subscriptions.sql.
150	  const { error: subscriptionError } = await supabase.rpc("start_trial", {
151	    p_business_id: business.id,
152	  });
153	
154	  if (subscriptionError) {
155	    return { error: subscriptionError.message };
156	  }
157	
158	  const copyFromBusinessId = (formData.get("copyFromBusinessId") as string) || null;
159	  if (copyFromBusinessId) {
160	    // RLS pada `businesses` sudah membatasi query ini ke milik user sendiri —
161	    // baris kosong berarti bukan pemiliknya (atau ID salah), jadi dilewati
162	    // begitu saja tanpa error, bukan diblokir secara eksplisit.
163	    const { data: sourceBusiness } = await supabase
164	      .from("businesses")
165	      .select("id")
166	      .eq("id", copyFromBusinessId)
167	      .single();
168	
169	    if (sourceBusiness) {
170	      await copyMenuFromBusiness(supabase, business.id, copyFromBusinessId);
171	    }
172	  }
173	
174	  redirect(`/business/${business.id}/billing`);
175	}
